const aGOverviewTreeIssues = `-- name: AGOverviewTreeIssues :many
WITH RECURSIVE tree AS (
    SELECT i.id
    FROM issue i
    WHERE i.workspace_id = $1
      AND (
        i.id = $2::uuid
        OR (
          $3::text IS NOT NULL
          AND (
            i.metadata @> jsonb_build_object('jira_key', $3::text)
            OR i.metadata @> jsonb_build_object('review_jira', $3::text)
            OR i.metadata @> jsonb_build_object('source_key', $3::text)
          )
        )
      )
    UNION
    SELECT c.id
    FROM issue c
    JOIN tree t ON c.parent_issue_id = t.id
    WHERE c.workspace_id = $1
      AND (
        $4::text IS NULL
        OR NOT (
          COALESCE(NULLIF(c.metadata->>'jira_key', ''), $4::text) <> $4::text
          OR COALESCE(NULLIF(c.metadata->>'review_jira', ''), $4::text) <> $4::text
          OR COALESCE(NULLIF(c.metadata->>'source_key', ''), $4::text) <> $4::text
        )
      )
)
SELECT
    i.id,
    i.number,
    i.title,
    i.status,
    i.parent_issue_id,
    i.created_at,
    i.updated_at,
    COALESCE(i.metadata->>'unit_flow', '')::text AS unit_flow,
    (CASE WHEN jsonb_typeof(i.metadata->'review_round') = 'number'
          THEN (i.metadata->>'review_round')::numeric::int ELSE -1 END)::int AS review_round,
    (i.metadata ? 'pr_url'
        OR EXISTS (SELECT 1 FROM issue_pull_request ipr WHERE ipr.issue_id = i.id))::boolean AS has_pr,
    (NOT EXISTS (SELECT 1 FROM issue k WHERE k.parent_issue_id = i.id))::boolean AS is_leaf
FROM tree
JOIN issue i ON i.id = tree.id
ORDER BY i.created_at, i.number
`

